Below is the complete five-module warehouse inventory system. Each module is standalone-standard-library only (Python 3.11).

### models.py
```python
"""Data models for the warehouse inventory system.

Every piece of on-disk state is expressed as the plain dictionary produced
by ``to_dict()`` and restored by ``from_dict()``, matching the JSON layout
used by ``storage.JsonStore``:

    {"products": [...], "locations": [...], "stock": [...], "movements": [...]}
"""

from dataclasses import dataclass, asdict
from typing import Any

MOVEMENT_KINDS = ("receive", "ship", "transfer", "adjust")


@dataclass
class Product:
    sku: str
    name: str
    unit_cost: float
    reorder_point: int

    def to_dict(self) -> dict[str, Any]:
        return asdict(self)

    @classmethod
    def from_dict(cls, d: dict[str, Any]) -> "Product":
        return cls(
            sku=str(d["sku"]),
            name=str(d["name"]),
            unit_cost=float(d["unit_cost"]),
            reorder_point=int(d["reorder_point"]),
        )


@dataclass
class Location:
    code: str
    capacity: int

    def to_dict(self) -> dict[str, Any]:
        return asdict(self)

    @classmethod
    def from_dict(cls, d: dict[str, Any]) -> "Location":
        return cls(code=str(d["code"]), capacity=int(d["capacity"]))


@dataclass
class StockLevel:
    sku: str
    location_code: str
    quantity: int

    def to_dict(self) -> dict[str, Any]:
        return asdict(self)

    @classmethod
    def from_dict(cls, d: dict[str, Any]) -> "StockLevel":
        return cls(
            sku=str(d["sku"]),
            location_code=str(d["location_code"]),
            quantity=int(d["quantity"]),
        )


@dataclass
class Movement:
    kind: str  # one of MOVEMENT_KINDS
    sku: str
    qty: int
    src: str | None
    dst: str | None
    ts: int
    ref: str

    def __post_init__(self) -> None:
        if self.kind not in MOVEMENT_KINDS:
            raise ValueError(
                f"unknown movement kind {self.kind!r}; expected one of {list(MOVEMENT_KINDS)}"
            )

    def to_dict(self) -> dict[str, Any]:
        return asdict(self)

    @classmethod
    def from_dict(cls, d: dict[str, Any]) -> "Movement":
        return cls(
            kind=str(d["kind"]),
            sku=str(d["sku"]),
            qty=int(d["qty"]),
            src=d.get("src"),
            dst=d.get("dst"),
            ts=int(d["ts"]),
            ref=str(d["ref"]),
        )
