### storage.py
```python
"""JSON-file persistence for the warehouse inventory system.

On-disk format (exactly this object; every value is a list of dicts, so an
external fixture may write this file directly and JsonStore reads it as-is):

    {
      "products":  [Product.to_dict(), ...],
      "locations": [Location.to_dict(), ...],
      "stock":     [StockLevel.to_dict(), ...],
      "movements": [Movement.to_dict(), ...]
    }

Saves are atomic: the payload is written to a temporary file in the same
directory, flushed + fsynced, then moved into place with ``os.replace()``.
"""

import json
import os
import tempfile
from typing import Any

from models import Location, Movement, Product, StockLevel

_DATA_KEYS = ("products", "locations", "stock", "movements")


class JsonStore:
    def __init__(self, path: str):
        self.path = path
        self._data: dict[str, Any] = self.load()

    # ------------------------------------------------------------------ disk I/O
    def _empty_data(self) -> dict[str, Any]:
        return {key: [] for key in _DATA_KEYS}

    def load(self) -> dict[str, Any]:
        """(Re)read the on-disk JSON object and return it.

        If the file does not exist yet, an empty structure is returned (and
        remembered in memory) so a fresh database can be bootstrapped via
        ``save()``.
        """
        if os.path.exists(self.path):
            with open(self.path, "r", encoding="utf-8") as fh:
                data = json.load(fh)
            if not isinstance(data, dict):
                raise ValueError(f"{self.path!r} does not contain a JSON object")
            for key in _DATA_KEYS:
                value = data.setdefault(key, [])
                if not isinstance(value, list):
                    raise ValueError(f"{self.path!r}: field {key!r} must be a list")
        else:
            data = self._empty_data()
        self._data = data
        return data

    def save(self) -> None:
        """Atomically persist the current data (temp file, then os.replace)."""
        payload = {key: list(self._data.get(key, [])) for key in _DATA_KEYS}
        directory = os.path.dirname(os.path.abspath(self.path)) or "."
        fd, tmp_path = tempfile.mkstemp(prefix=".inventory-", suffix=".tmp", dir=directory)
        try:
            with os.fdopen(fd, "w", encoding="utf-8") as fh:
                json.dump(payload, fh, indent=2)
                fh.write("\n")
                fh.flush()
                os.fsync(fh.fileno())
            os.replace(tmp_path, self.path)
        except BaseException:
            try:
                os.unlink(tmp_path)
            except OSError:
                pass
            raise

    # ------------------------------------------------------------------ lookups
    def get_product(self, sku: str) -> Product:
        for entry in self._data["products"]:
            if entry.get("sku") == sku:
                return Product.from_dict(entry)
        raise KeyError(f"unknown product sku: {sku!r}")

    def get_location(self, code: str) -> Location:
        for entry in self._data["locations"]:
            if entry.get("code") == code:
                return Location.from_dict(entry)
        raise KeyError(f"unknown location code: {code!r}")

    def stock_at(self, sku: str, code: str) -> int:
        """Quantity of ``sku`` stored at ``code`` (0 when no entry exists)."""
        self.get_product(sku)    # KeyError when the sku is unknown
        self.get_location(code)  # KeyError when the location is unknown
        for entry in self._data["stock"]:
            if entry.get("sku") == sku and entry.get("location_code") == code:
                return int(entry.get("quantity", 0))
        return 0

    # ------------------------------------------------------------------ mutations (each persists immediately)
    def set_stock(self, sku: str, code: str, qty: int) -> None:
        self.get_product(sku)
        self.get_location(code)
        qty = int(qty)
        for entry in self._data["stock"]:
            if entry.get("sku") == sku and entry.get("location_code") == code:
                entry["quantity"] = qty
                self.save()
                return
        self._data["stock"].append(
            StockLevel(sku=sku, location_code=code, quantity=qty).to_dict()
        )
        self.save()

    def append_movement(self, movement: Movement | dict[str, Any]) -> None:
        if isinstance(movement, Movement):
            entry = movement.to_dict()
        elif isinstance(movement, dict):
            entry = movement
        else:
            raise TypeError("append_movement expects a Movement or a dict")
        self._data["movements"].append(entry)
        self.save()
```

### rules.py
```python
"""Business rules for the warehouse inventory system.

``Inventory`` wraps a ``storage.JsonStore`` and enforces:

* receive/ship/transfer quantities must be > 0 (ValueError); an adjust
  delta must be non-zero (ValueError);
* ship/transfer may never take more than the on-hand quantity at the
  source location (InsufficientStock); an adjust may never push a
  location's quantity below zero (InsufficientStock);
* receive/transfer (and positive adjust) may never push the summed
  quantity of ALL skus at a location past that Location's capacity
  (CapacityExceeded); exactly reaching capacity is allowed;
* every successful call appends exactly one Movement and persists the
  new state;
* ``ref`` must be a non-empty string (ValueError) and unique across all
  movements ever recorded (DuplicateRef); every failing call changes
  nothing because all validation happens before any mutation.
"""

import time

from models import Location, Movement, Product


class InsufficientStock(Exception):
    """An operation tried to take more stock than a location holds."""


class CapacityExceeded(Exception):
    """An operation tried to put more stock into a location than its capacity."""


class DuplicateRef(Exception):
    """A movement reference id was already used by an earlier movement."""


def _now() -> int:
    """Current timestamp as an int (tests may patch this)."""
    return int(time.time())


class Inventory:
    def __init__(self, store):
        self.store = store

    # ------------------------------------------------------------------ validation helpers
    def _check_qty_positive(self, qty: int) -> None:
        if qty <= 0:
            raise ValueError(f"qty must be > 0, got {qty!r}")

    def _check_ref_unused(self, ref) -> None:
        if not isinstance(ref, str) or not ref:
            raise ValueError("ref must be a non-empty string")
        for entry in self.store.load()["movements"]:
            if entry.get("ref") == ref:
                raise DuplicateRef(f"ref {ref!r} was already used")

    def _require_product(self, sku: str) -> Product:
        return self.store.get_product(sku)  # KeyError when unknown

    def _require_location(self, code: str) -> Location:
        return self.store.get_location(code)  # KeyError when unknown

    def _location_load(self, code: str) -> int:
        """Total quantity of ALL skus currently stored at ``code``."""
        return sum(
            int(entry.get("quantity", 0))
            for entry in self.store.load()["stock"]
            if entry.get("location_code") == code
        )

    def _check_capacity(self, code: str, incoming: int) -> None:
        capacity = self._require_location(code).capacity
        projected = self._location_load(code) + incoming
        if projected > capacity:
            raise CapacityExceeded(
                f"location {code!r} would hold {projected} units, capacity is {capacity}"
            )

    def _record(self, kind: str, sku: str, qty: int,
                src: str | None, dst: str | None, ref: str) -> Movement:
        movement = Movement(kind=kind, sku=sku, qty=int(qty),
                            src=src, dst=dst, ts=_now(), ref=ref)
        self.store.append_movement(movement)
        return movement

    # ------------------------------------------------------------------ operations
    def receive(self, sku: str, qty: int, dst: str, ref: str) -> Movement:
        """Add ``qty`` units of ``sku`` into location ``dst``."""
        self._check_qty_positive(qty)
        self._check_ref_unused(ref)
        self._require_product(sku)
        self._require_location(dst)
        self._check_capacity(dst, qty)
        self.store.set_stock(sku, dst, self.store.stock_at(sku, dst) + qty)
        return self._record("receive", sku, qty, None, dst, ref)

    def ship(self, sku: str, qty: int, src: str, ref: str) -> Movement:
        """Remove ``qty`` units of ``sku`` from location ``src``."""
        self._check_qty_positive(qty)
        self._check_ref_unused(ref)
        self._require_product(sku)
        self._require_location(src)
        available = self.store.stock_at(sku, src)
        if qty > available:
            raise InsufficientStock(
                f"location {src!r} holds {available} of {sku!r}, cannot ship {qty}"
            )
        self.store.set_stock(sku, src, available - qty)
        return self._record("ship", sku, qty, src, None, ref)

    def transfer(self, sku: str, qty: int, src: str, dst: str, ref: str) -> Movement:
        """Move ``qty`` units of ``sku`` from location ``src`` to ``dst``."""
        self._check_qty_positive(qty)
        if src == dst:
            raise ValueError("transfer requires distinct src and dst")
        self._check_ref_unused(ref)
        self._require_product(sku)
        self._require_location(src)
        self._require_location(dst)
        available = self.store.stock_at(sku, src)
        if qty > available:
            raise InsufficientStock(
                f"location {src!r} holds {available} of {sku!r}, cannot transfer {qty}"
            )
        self._check_capacity(dst, qty)
        self.store.set_stock(sku, src, available - qty)
        self.store.set_stock(sku, dst, self.store.stock_at(sku, dst) + qty)
        return self._record("transfer", sku, qty, src, dst, ref)

    def adjust(self, sku: str, qty_delta: int, loc: str, ref: str) -> Movement:
        """Apply a signed delta to the stock of ``sku`` at ``loc``."""
        if qty_delta == 0:
            raise ValueError("qty_delta must be non-zero")
        self._check_ref_unused(ref)
        self._require_product(sku)
        self._require_location(loc)
        projected = self.store.stock_at(sku, loc) + qty_delta
        if projected < 0:
            raise InsufficientStock(
                f"adjust would leave {sku!r} at {loc!r} with {projected} units"
            )
        if qty_delta > 0:
            self._check_capacity(loc, qty_delta)
        self.store.set_stock(sku, loc, projected)
        return self._record("adjust", sku, qty_delta, None, loc, ref)

    # ------------------------------------------------------------------ reporting
    def total_on_hand(self, sku: str) -> int:
        self._require_product(sku)
        return sum(
            int(entry.get("quantity", 0))
            for entry in self.store.load()["stock"]
            if entry.get("sku") == sku
        )

    def below_reorder(self) -> list[str]:
        result = []
        for entry in self.store.load()["products"]:
            product = self.store.get_product(entry["sku"])
            if self.total_on_hand(product.sku) < product.reorder_point:
                result.append(product.sku)
        return result

    def valuation(self) -> float:
        total = 0.0
        for entry in self.store.load()["stock"]:
            product = self.store.get_product(entry["sku"])
            total += int(entry.get("quantity", 0)) * product.unit_cost
        return float(total)

    def ledger(self, sku: str) -> list[Movement]:
        self._require_product(sku)
        movements = [
            Movement.from_dict(entry)
            for entry in self.store.load()["movements"]
            if entry.get("sku") == sku
        ]
        movements.sort(key=lambda m: m.ts)  # stable: equal ts keep arrival order
        return movements
```

### cli.py
```python
"""Command-line front end for the warehouse inventory system.

Usage examples:

    python cli.py --db db.json receive WIDGET 5 --dst L1 --ref r001
    python cli.py --db db.json ship WIDGET 2 --src L1 --ref r002
    python cli.py --db db.json transfer WIDGET 3 --src L1 --dst L2 --ref r003
    python cli.py --db db.json adjust WIDGET -1 --loc L2 --ref r004
    python cli.py --db db.json report

Every command prints exactly one JSON line. Successful operations print an
object with ``"ok": true`` plus operation details; ``report`` prints
``{"valuation": ..., "below_reorder": [...], "total_units": ...}``. Failures
print ``{"ok": false, "error": <ExceptionName>, "message": ...}`` and the
process exits with status 1.
"""

import argparse
import json
import sys

from rules import CapacityExceeded, DuplicateRef, InsufficientStock, Inventory
from storage import JsonStore


def build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(prog="cli", description="warehouse inventory CLI")
    parser.add_argument("--db", required=True, help="path to the JSON store file")
    sub = parser.add_subparsers(dest="command", required=True, metavar="command")

    def op_parser(name: str, help_text: str) -> argparse.ArgumentParser:
        sp = sub.add_parser(name, help=help_text)
        sp.add_argument("sku", help="product sku")
        sp.add_argument("qty", type=int, help="quantity (positive)")
        sp.add_argument("--ref", required=True, help="unique reference id for the movement")
        return sp

    p_receive = op_parser("receive", "add stock into a location")
    p_receive.add_argument("--dst", required=True, help="destination location code")

    p_ship = op_parser("ship", "remove stock from a location")
    p_ship.add_argument("--src", required=True, help="source location code")

    p_transfer = op_parser("transfer", "move stock between locations")
    p_transfer.add_argument("--src", required=True, help="source location code")
    p_transfer.add_argument("--dst", required=True, help="destination location code")

    p_adjust = sub.add_parser("adjust", "apply a signed stock delta at a location")
    p_adjust.add_argument("sku", help="product sku")
    p_adjust.add_argument("delta", type=int, help="signed quantity delta (non-zero)")
    p_adjust.add_argument("--loc", required=True, help="affected location code")
    p_adjust.add_argument("--ref", required=True, help="unique reference id for the movement")

    sub.add_parser("report", help="print valuation, below-reorder skus and total units")
    return parser


def main(argv: list[str] | None = None) -> int:
    args = build_parser().parse_args(argv)
    try:
        store = JsonStore(args.db)
        inv = Inventory(store)

        if args.command == "receive":
            movement = inv.receive(args.sku, args.qty, args.dst, args.ref)
            result = {
                "ok": True,
                "op": "receive",
                "sku": movement.sku,
                "qty": movement.qty,
                "dst": movement.dst,
                "ref": movement.ref,
                "ts": movement.ts,
                "quantity_now": store.stock_at(movement.sku, movement.dst),
            }
        elif args.command == "ship":
            movement = inv.ship(args.sku, args.qty, args.src, args.ref)
            result = {
                "ok": True,
                "op": "ship",
                "sku": movement.sku,
                "qty": movement.qty,
                "src": movement.src,
                "ref": movement.ref,
                "ts": movement.ts,
                "quantity_now": store.stock_at(movement.sku, movement.src),
            }
        elif args.command == "transfer":
            movement = inv.transfer(args.sku, args.qty, args.src, args.dst, args.ref)
            result = {
                "ok": True,
                "op": "transfer",
                "sku": movement.sku,
                "qty": movement.qty,
                "src": movement.src,
                "dst": movement.dst,
                "ref": movement.ref,
                "ts": movement.ts,
                "src_quantity_now": store.stock_at(movement.sku, movement.src),
                "dst_quantity_now": store.stock_at(movement.sku, movement.dst),
            }
        elif args.command == "adjust":
            movement = inv.adjust(args.sku, args.delta, args.loc, args.ref)
            result = {
                "ok": True,
                "op": "adjust",
                "sku": movement.sku,
                "delta": movement.qty,
                "loc": movement.dst,
                "ref": movement.ref,
                "ts": movement.ts,
                "quantity_now": store.stock_at(movement.sku, movement.dst),
            }
        else:  # report
            result = {
                "valuation": inv.valuation(),
                "below_reorder": inv.below_reorder(),
                "total_units": sum(
                    int(entry.get("quantity", 0)) for entry in store.load()["stock"]
                ),
            }

        print(json.dumps(result))
        return 0
    except (
        ValueError,
        KeyError,
        OSError,
        InsufficientStock,
        CapacityExceeded,
        DuplicateRef,
    ) as exc:
        print(json.dumps({"ok": False, "error": type(exc).__name__, "message": str(exc)}))
        return 1


if __name__ == "__main__":
    sys.exit(main())
```

### tests.py
```python
"""Unit tests for the warehouse inventory system.

Run with:  python -m unittest tests -v
"""

import contextlib
import io
import json
import os
import tempfile
import unittest
from unittest import mock

import rules
from cli import main as cli_main
from models import Location, Movement, Product, StockLevel
from rules import CapacityExceeded, DuplicateRef, InsufficientStock, Inventory
from storage import JsonStore


def _dicts(items):
    return [item.to_dict() if hasattr(item, "to_dict") else dict(item) for item in items]


class WarehouseTestBase(unittest.TestCase):
    """Common fixture: two products, three locations, some initial stock."""

    def setUp(self):
        tmp = tempfile.TemporaryDirectory()
        self.addCleanup(tmp.cleanup)
        self.tmpdir = tmp.name
        self.db_path = os.path.join(self.tmpdir, "db.json")
        self.products = [Product("A", "Widget", 2.50, 10), Product("B", "Gadget", 4.00, 5)]
        self.locations = [Location("L1", 100), Location("L2", 10), Location("L3", 3)]
        self.stock = [StockLevel("A", "L1", 20), StockLevel("A", "L2", 5), StockLevel("B", "L1", 4)]
        self.write_db(self.products, self.locations, self.stock, [])

    def write_db(self, products=(), locations=(), stock=(), movements=()):
        """Write the on-disk JSON file directly, exactly in the fixed format."""
        data = {
            "products": _dicts(products),
            "locations": _dicts(locations),
            "stock": _dicts(stock),
            "movements": _dicts(movements),
        }
        with open(self.db_path, "w", encoding="utf-8") as fh:
            json.dump(data, fh, indent=2)
        return data

    def store(self):
        return JsonStore(self.db_path)

    def inv(self):
        return Inventory(self.store())

    def snapshot(self):
        data = self.store().load()
        return {
            "stock": [dict(entry) for entry in data["stock"]],
            "movements": [dict(entry) for entry in data["movements"]],
        }


class ModelTests(unittest.TestCase):
    def test_roundtrip_all_models(self):
        product = Product("A", "Widget", 2.5, 10)
        self.assertEqual(Product.from_dict(product.to_dict()), product)
        location = Location("L1", 100)
        self.assertEqual(Location.from_dict(location.to_dict()), location)
        level = StockLevel("A", "L1", 7)
        self.assertEqual(StockLevel.from_dict(level.to_dict()), level)
        movement = Movement("transfer", "A", 3, "L1", "L2", 123, "r1")
        self.assertEqual(Movement.from_dict(movement.to_dict()), movement)

    def test_movement_dict_shape(self):
        movement = Movement("receive", "A", 5, None, "L1", 42, "r9")
        self.assertEqual(
            movement.to_dict(),
            {"kind": "receive", "sku": "A", "qty": 5,
             "src": None, "dst": "L1", "ts": 42, "ref": "r9"},
        )

    def test_movement_rejects_unknown_kind(self):
        with self.assertRaises(ValueError):
            Movement("steal", "A", 1, "L1", None, 1, "r0")

    def test_from_dict_ignores_extra_keys(self):
        product = Product.from_dict(
            {"sku": "X", "name": "N", "unit_cost": 1, "reorder_point": 2, "extra": True}
        )
        self.assertEqual(product, Product("X", "N", 1.0, 2))


class StorageTests(WarehouseTestBase):
    def test_load_reads_fixture_in_exact_format(self):
        data = self.store().load()
        self.assertEqual(list(data.keys()), ["products", "locations", "stock", "movements"])
        self.assertEqual(
            data["products"][0],
            {"sku": "A", "name": "Widget", "unit_cost": 2.5, "reorder_point": 10},
        )
        self.assertEqual(data["movements"], [])

    def test_missing_file_starts_empty_and_save_creates_it(self):
        path = os.path.join(self.tmpdir, "fresh.json")
        store = JsonStore(path)
        self.assertEqual(
            store.load(), {"products": [], "locations": [], "stock": [], "movements": []}
        )
        store.save()
        self.assertTrue(os.path.exists(path))
        with open(path, encoding="utf-8") as fh:
            self.assertEqual(list(json.load(fh).keys()),
                             ["products", "locations", "stock", "movements"])

    def test_save_roundtrip_through_new_instance(self):
        store = self.store()
        store.set_stock("A", "L1", 15)
        store.set_stock("B", "L2", 3)  # creates a new StockLevel entry
        movement = Movement("receive", "B", 3, None, "L2", 7, "m1")
        store.append_movement(movement)
        fresh = JsonStore(self.db_path)
        self.assertEqual(fresh.stock_at("A", "L1"), 15)
        self.assertEqual(fresh.stock_at("B", "L2"), 3)
        self.assertEqual(
            [Movement.from_dict(m) for m in fresh.load()["movements"]], [movement]
        )

    def test_get_product_and_location(self):
        store = self.store()
        self.assertEqual(store.get_product("A"), Product("A", "Widget", 2.5, 10))
        self.assertEqual(store.get_location("L2"), Location("L2", 10))
        with self.assertRaises(KeyError):
            store.get_product("MISSING")
        with self.assertRaises(KeyError):
            store.get_location("NOWHERE")

    def test_stock_at_defaults_to_zero_and_validates_keys(self):
        store = self.store()
        self.assertEqual(store.stock_at("B", "L2"), 0)  # known sku/location, no entry yet
        with self.assertRaises(KeyError):
            store.stock_at("MISSING", "L1")
        with self.assertRaises(KeyError):
            store.stock_at("A", "NOWHERE")

    def test_set_stock_rejects_unknown_sku_or_location(self):
        store = self.store()
        with self.assertRaises(KeyError):
            store.set_stock("MISSING", "L1", 1)
