    def test_receive_capacity_counts_every_sku_at_the_location(self):
        self.store().set_stock("A", "L3", 2)  # L3 already holds 2 units (capacity 3)
        inv = self.inv()
        before = self.snapshot()
        with self.assertRaises(CapacityExceeded):
            inv.receive("B", 2, "L3", "r1")  # 2 + 2 = 4 > 3
        self.assertEqual(self.snapshot(), before)
        inv.receive("B", 1, "L3", "r2")      # 2 + 1 = 3 == capacity -> allowed
        self.assertEqual(self.store().stock_at("A", "L3"), 2)
        self.assertEqual(self.store().stock_at("B", "L3"), 1)

    def test_receive_into_empty_location_up_to_capacity(self):
        inv = self.inv()
        with self.assertRaises(CapacityExceeded):
            inv.receive("B", 4, "L3", "r1")  # capacity of L3 is 3
        self.assertEqual(self.store().stock_at("B", "L3"), 0)
        inv.receive("B", 3, "L3", "r2")
        self.assertEqual(self.store().stock_at("B", "L3"), 3)

    # ---------------- ship ----------------
    def test_ship_updates_stock_and_appends_one_movement(self):
        inv = self.inv()
        movement = inv.ship("A", 6, "L1", "s1")
