        before = self.snapshot()
        with self.assertRaises(InsufficientStock):
            inv.ship("A", 6, "L2", "s1")  # L2 holds only 5
        self.assertEqual(self.snapshot(), before)

    def test_ship_uses_only_the_source_location(self):
